    const auditLog = [];

    function logSignInAttempt(memberId, outcome) {
        const timestamp = new Date().toISOString();
        auditLog.push({ memberId, timestamp, outcome });
        console.log("Audit Log:", auditLog);
    }

    function hashPassword(password) {
        // Simple hash function for demo purposes
        let hash = 0, i, chr;
        for (i = 0; i < password.length; i++) {
            chr = password.charCodeAt(i);
            hash = ((hash << 5) - hash) + chr;
            hash |= 0; // Convert to 32bit integer
        }
        return hash.toString();
    }

    function handleSignIn() {
        const memberId = document.getElementById("member-id-signin").value;
        const password = document.getElementById("password").value;
        const statusDiv = document.getElementById("sign-in-status");

        if (mockMembers[memberId] && mockMembers[memberId].hashedPassword === hashPassword(password)) {
            logSignInAttempt(memberId, "success");
            statusDiv.textContent = "Sign in successful.";
            document.getElementById("sign-in").style.display = "none";
            document.getElementById("claim-form").style.display = "block";
        } else {
            logSignInAttempt(memberId, "failure");
            statusDiv.textContent = "Invalid Member ID or Password.";
        }
    }

    function lookupMember() {
        const memberId = document.getElementById("member-id").value;
        const detailsDiv = document.getElementById("member-details");
        if (mockMembers[memberId]) {
            const member = mockMembers[memberId];
            detailsDiv.innerHTML = `<p>Name: ${member.name}</p><p>Member Since: ${member.memberSince}</p>`;
        } else {
            detailsDiv.innerHTML = `<p>Member not found.</p>`;
        }
    }

    function updateFileList() {
        const input = document.getElementById("documents");
        const list = document.getElementById("file-list");
        list.innerHTML = "";
        for (let i = 0; i < input.files.length; i++) {
            const li = document.createElement("li");
            li.textContent = input.files[i].name;
            list.appendChild(li);
        }
    }

    function generateReferenceNumber() {
        const year = new Date().getFullYear();
        const randomSegment = Math.floor(1000 + Math.random() * 9000);
        return `MS-${year}-08-${randomSegment}`;
    }

    function submitForm() {
        document.getElementById("claim-form").style.display = "none";
        const refNumber = generateReferenceNumber();
        document.getElementById("reference-number").textContent = refNumber;
        document.getElementById("confirmation").style.display = "block";
    }
</script>

